{
  "parameters": [
    {
      "name": "dependency_groups",
      "type": "object",
      "description": "The parsed contents of the [dependency-groups] table from pyproject.toml",
      "required": true
    },
    {
      "name": "groups",
      "type": "array",
      "items": {
        "type": "string"
      },
      "description": "The name of the group(s) to resolve",
      "required": true
    }
  ],
  "direct_call": "packaging.dependency_groups.resolve_dependency_groups(dependency_groups, *groups)",
  "samples": [
    {
      "dependency_groups": {
        "dev": ["pytest", "black"],
        "docs": ["sphinx"]
      },
      "groups": ["dev"]
    },
    {
      "dependency_groups": {
        "dev": ["pytest", "black"],
        "docs": ["sphinx"]
      },
      "groups": ["dev", "docs"]
    },
    {
      "dependency_groups": {
        "optional": ["requests", {"platform": "win32", "requirement": "pywin32"}]
      },
      "groups": ["optional"]
    },
    {
      "dependency_groups": {
        "base": ["click"],
        "extra": ["flask"]
      },
      "groups": []
    },
    {
      "dependency_groups": {},
      "groups": ["nonexistent"]
    }
  ]
}

