from packaging.direct_url import DirectUrl
from typing import Any, Mapping


def direct_url_from_dict(direct_url_dict: dict[str, Any]) -> dict[str, Any]:
    """Create and validate a DirectUrl instance from a JSON dictionary. direct_url_dict: A JSON dictionary representing a direct URL, e.g. {"url": "https://example.com/package.tar.gz"} -> {"url": "https://example.com/package.tar.gz"}."""
    try:
        direct_url = DirectUrl.from_dict(direct_url_dict)
        return {"url": direct_url.url}
    except Exception as e:
        raise ValueError(f"Invalid direct URL dictionary: {direct_url_dict!r}") from e
